<?php require_once __DIR__.'/../includes/functions.php';$u=require_login();page_start('Settings'); ?><div class="row g-4"><div class="col-lg-7"><div class="card"><div class="card-body"><h2 class="h5">Account</h2><p class="text-secondary">Signed in as <?= e($u['email']) ?>.</p><a href="edit-profile.php" class="btn btn-outline-primary">Edit profile and preferences</a><hr><h2 class="h5">Rate a study partner</h2><p class="small text-secondary">Ratings are available after you have an accepted partner connection.</p><form method="post" action="../actions/rating.php"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><select class="form-select mb-2" name="ratee_id" required><option value="">Choose partner</option><?php $q=db()->prepare("SELECT DISTINCT u.id,u.name FROM users u JOIN study_requests r ON r.status='accepted' AND ((r.sender_id=? AND r.receiver_id=u.id) OR (r.receiver_id=? AND r.sender_id=u.id))");$q->execute([(int)$u['id'],(int)$u['id']]);foreach($q as $r): ?><option value="<?= $r['id'] ?>"><?= e($r['name']) ?></option><?php endforeach ?></select><select class="form-select mb-2" name="rating"><option value="5">5 stars</option><option value="4">4 stars</option><option value="3">3 stars</option><option value="2">2 stars</option><option value="1">1 star</option></select><textarea class="form-control mb-2" name="feedback" maxlength="500" placeholder="Short feedback (optional)"></textarea><button class="btn btn-primary">Submit rating</button></form></div></div></div></div><?php page_end(); ?>
